def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Locate two separated patterned row bands and find their horizontal offset
    # by matching the foreground/background pattern across corresponding rows.
    active = [any(v != 9 for v in row) for row in grid]
    bands = []
    i = 0
    while i < h:
        if not active[i]:
            i += 1
            continue
        a = i
        while i < h and active[i]:
            i += 1
        bands.append((a, i))
    if len(bands) < 2:
        return out
    (a, b), (c, d) = bands[0], bands[-1]
    n = min(b - a, d - c)
    best = None
    for shift in range(-(w - 1), w):
        matches = total = 0
        for k in range(n):
            for x in range(w):
                y = x + shift
                if 0 <= y < w:
                    total += 1
                    matches += ((grid[a+k][x] == 4) == (grid[c+k][y] == 4))
        score = matches / total if total else 0
        if best is None or score > best[0]:
            best = (score, shift)
    shift = best[1]
    for k in range(n):
        for x in range(w):
            y = x + shift
            if 0 <= y < w and grid[a+k][x] == 4 and grid[c+k][y] == 9:
                out[c+k][y] = 1
    return out
